 static int count;static string root;static void Check(bool ok,string why){if(!ok)throw new Exception(why);count++;Console.WriteLine("PASS "+why);}
 public const string Original="The enormous bag he carried looked almost unreal.";
 public const string Fixed="The huge bag he carried looked almost unreal.";
 sealed class Voice:KokoroEngine {
  public static readonly List<string> Requests=new List<string>();public static double OriginalSeconds=3;public static bool Broken;public static readonly Dictionary<string,double> Durations=new Dictionary<string,double>();
  public override void CheckFiles(){if(Broken)throw new IOException("fixture model failure");}
  public override Wave Generate(string text,double speed,string path){Requests.Add(text);double seconds=Durations.ContainsKey(text)?Durations[text]:text==Original?OriginalSeconds:3;return Tone(seconds/speed);}
 }
 sealed class Writer:ITextRewriter {
  public int Calls;public bool Repeat,RepeatAny,UncertainFirst,Invent;
  public string Rewrite(string prompt,Func<bool> cancel,Action<string> progress){Calls++;if(RepeatAny){int from=prompt.IndexOf("\nCues: ")+7;int end=prompt.IndexOf("\nAvoid previous",from);return prompt.Substring(from,end-from);}string text=Repeat?Original:Invent?"The enormous bag started glowing as he carried it.":UncertainFirst&&Calls==1?"The enormous bag that he carried looked almost unreal.":Fixed;return LocalAi.Json(new AiRewriteText{cues=new List<AiCueText>{new AiCueText{id=1,text=text}}});}
 }
 sealed class Translator:ITextRewriter {
  public int Calls;public bool Broken;public List<string> Prompts=new List<string>();
  public string Rewrite(string prompt,Func<bool> cancel,Action<string> progress){Calls++;Prompts.Add(prompt);if(Broken)throw new IOException("fixture translation failed");return prompt.StartsWith("TASK=TRANSLATION_VERIFY")?"{\"items\":[{\"id\":1,\"ok\":true,\"source_subject_type\":\"object\",\"target_subject_type\":\"object\",\"reason\":\"fixture\"}]}":"{\"cues\":[{\"id\":1,\"text\":\"Chiếc túi khổng lồ anh mang trông gần như không thật.\"}]}";}
 }
 static Wave Tone(double seconds){return new Wave{Rate=24000,Samples=Enumerable.Range(0,(int)Math.Round(seconds*24000)).Select(i=>(short)(5000*Math.Cos(i*.063))).ToArray()};}
 static Voice Engine(){return new Voice{Root=root,VoiceName="fixture",DeviceMode="cpu"};}
 static VoiceSettings Settings(int ai=2){return new VoiceSettings{AiMode=ai,Mode=0,Breathing=(int)BreathMode.None,Normalize=false,GentleFit=false,Slow=false,Gap=0,Punctuation=1,CommaPause=0,StopPause=0,QuestionPause=0,ParagraphPause=0,MinSpeed=.9,MaxSpeed=1.25};}
 static string Source(string name){string dir=Path.Combine(root,name);Directory.CreateDirectory(dir);string path=Path.Combine(dir,name+".srt");File.WriteAllText(path,Scripts.ToSrt(new List<Cue>{new Cue{Id=1,Start=0,End=3.2,Text=Original},new Cue{Id=2,Start=3.3,End=6.5,Text="This second sentence stays exactly as supplied."}}));return path;}
 static RenderOptions Options(string path,Translator t){var o=AudioRepair.Options(Settings().Xml().ToString());o.Translator=t;o.TranslationCacheRoot=Path.Combine(Path.GetDirectoryName(path),"translation-cache");o.ReportContext=new VoiceReportContext{SourcePath=path};return o;}
 static WorkflowResult Run(string path,int mode,RenderOptions o,Writer writer,List<Cue> draft=null){
  var input=draft??BatchJob.Load(path).Cues;
  Func<List<Cue>,RenderOptions,string,KokoroEngine,Action<int,string>,List<Cue>> prepare=(words,options,source,owner,progress)=>{
   var settings=Settings();settings.Mode=options.Anchored?2:0;settings.Punctuation=(int)options.Punctuation;var p=AiRepairSession.Open(source,words,Path.Combine(Path.GetDirectoryName(path),"state"),settings,true,"fixture217");options.AiRepair=p;options.AiReportPath=p.Report;owner.ReleaseModels();AiTimeline.Run(p,writer,role=>Engine(),()=>owner.Cancelled,progress,true,true,0,true);return p.Effective();
  };
  using(var e=Engine())return WorkflowRunner.Run(input,e,o,OutputFiles.Beside(path),mode,prepare,(n,m)=>{});
 }
 static string[] Reports(string path){return Directory.GetFiles(Path.GetDirectoryName(path),"*.txt");}
